-- EcoWealth MySQL schema (XAMPP / MariaDB)
-- Tables: user, appointment, products, audit
-- Run: mysql -u root < database/schema.sql

CREATE DATABASE IF NOT EXISTS ecowealth
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

CREATE USER IF NOT EXISTS 'ecowealth'@'localhost' IDENTIFIED BY 'ecowealth_pass';
GRANT ALL PRIVILEGES ON ecowealth.* TO 'ecowealth'@'localhost';
FLUSH PRIVILEGES;

USE ecowealth;

-- Remove legacy tables from earlier schema versions
SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS audit;
DROP TABLE IF EXISTS appointment;
DROP TABLE IF EXISTS appointments;
DROP TABLE IF EXISTS appointment_services;
DROP TABLE IF EXISTS clinic;
DROP TABLE IF EXISTS products;
DROP TABLE IF EXISTS `user`;
SET FOREIGN_KEY_CHECKS = 1;

-- ---------------------------------------------------------------------------
-- user (auto-increment PK)
-- ---------------------------------------------------------------------------
CREATE TABLE `user` (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  role ENUM('patient', 'admin', 'staff') NOT NULL DEFAULT 'patient',
  full_name VARCHAR(120) NOT NULL,
  phone VARCHAR(32) NOT NULL,
  email VARCHAR(254) NULL,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_user_phone (phone),
  KEY idx_user_role (role),
  KEY idx_user_active (is_active)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------------
-- appointment (auto-increment PK, links to user)
-- ---------------------------------------------------------------------------
CREATE TABLE appointment (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id BIGINT UNSIGNED NOT NULL,
  reference_id CHAR(8) NOT NULL,
  service_slug VARCHAR(64) NOT NULL,
  service_label VARCHAR(255) NOT NULL,
  preferred_date DATE NULL,
  preferred_time TIME NULL,
  notes TEXT NULL,
  status ENUM('pending', 'confirmed', 'cancelled') NOT NULL DEFAULT 'pending',
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
